entries[171200] = { ["name"] = "Vantus Rune Technique: Ny'alotha, the Waking City", ["text"] = "Rank 3\nBinds when picked up\nUse: Teaches you how to craft a Vantus Rune: Nya'lotha, the Waking City more efficiently.\nGreatly reduce the materials required to craft a Vantus Rune: Ny'alotha, the Waking City.\nRequires Kul Tiran Inscription (165)\nSell Price:\nVantus Rune: Ny'alotha, the Waking City\nUse: Attune yourself to the energies of the targeted Ny'alotha, the Waking City raid boss, increasing your Versatility by 2078 when fighting that boss. This effect lasts for an entire week.\n\nYou can only use one Vantus Rune per week.\nSell Price:\nRequires Light Parchment , Maroon Ink (15), Ultramarine Ink (7)" }
entries[171201] = { ["name"] = "Vantus Rune Technique: Ny'alotha, the Waking City", ["text"] = "Rank 2\nBinds when picked up\nUse: Teaches you how to craft a Vantus Rune: Nya'lotha, the Waking City more efficiently.\nReduce the materials required to craft a Vantus Rune: Ny'alotha, the Waking City.\nRequires Kul Tiran Inscription (165)\nSell Price:\nVantus Rune: Ny'alotha, the Waking City\nUse: Attune yourself to the energies of the targeted Ny'alotha, the Waking City raid boss, increasing your Versatility by 2078 when fighting that boss. This effect lasts for an entire week.\n\nYou can only use one Vantus Rune per week.\nSell Price:\nRequires Light Parchment , Maroon Ink (18), Ultramarine Ink (9)" }
entries[171202] = { ["name"] = "Vantus Rune Technique: Ny'alotha, the Waking City", ["text"] = "Rank 1\nBinds when picked up\nUse: Teaches you how to craft a Vantus Rune: Nya'lotha, the Waking City.\nCraft a Vantus Rune: Ny'alotha, the Waking City.\nRequires Kul Tiran Inscription (165)\nSell Price:\nVantus Rune: Ny'alotha, the Waking City\nUse: Attune yourself to the energies of the targeted Ny'alotha, the Waking City raid boss, increasing your Versatility by 2078 when fighting that boss. This effect lasts for an entire week.\n\nYou can only use one Vantus Rune per week.\nSell Price:\nRequires Light Parchment , Maroon Ink (20), Ultramarine Ink (10)" }
