entries[171312] = { ["name"] = "Recipe: Void Focus", ["text"] = "Binds when picked up\nUnique\nUse: Teaches you how to craft a Void Focus, an otherworldly crystal that harnesses the power of the N'Zoth needed to craft powerful pieces of armor.\n\"Dark runes skitter across the scroll, constantly rearranging and forming increasingly sinister shapes.\"" }
