entries[171318] = { ["name"] = "Recipe: Unbound Alchemist Stone", ["text"] = "Binds when picked up\nUnique\nUse: Teaches you how to craft an Unbound Alchemist Stone.\nCreate an Unbound Alchemist Stone.\nRequires Kul Tiran Alchemy (165)\n\nUnbound Alchemist Stone\nBinds when picked up\nUnique-Equipped: Alchemist Stone (1)\nTrinket\n+ 12 Versatility\n\nPrismatic Socket\n\nEquip: When you heal or deal damage you have a chance to increase your Strength, Agility, or Intellect by 31 for 15 sec. Your highest stat is always chosen.\nEquip: Increases the effect that healing and mana potions have on the wearer by 40%. This effect does not stack.\nRequires Kul Tiran Alchemy (165)\n\"Can be used for transmutations in place of a Philosopher's Stone.\"\nSell Price:\nRequires Zin'anthid (175), Anchor Weed (60), Expulsom (30)" }
entries[171320] = { ["name"] = "Void Focus", ["text"] = "Binds when picked up\nThis Item Begins a Quest\n\"Based on a design stolen from N'Zoth's forces, the power radiated by this dark crystal allows the wielder to craft powerful items.\"" }
entries[171323] = { ["name"] = "Spiritual Alchemy Stone", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+ 25 Versatility\nEquip: When you heal or deal damage you have a chance to increase your Strength, Agility, or Intellect by 67 for 15 sec. Your highest stat is always chosen.\nEquip: Increases the effect that healing and mana potions have on the wearer by 40%. This effect does not stack.\nRequires Shadowlands Alchemy (100)\n\"Can be used for transmutations in place of a Philosopher's Stone.\"\nSell Price:" }
