entries[171349] = { ["name"] = "Potion of Phantom Fire", ["text"] = "Use: Your attacks and spells have a chance to send out a fiery projection at your target dealing 6270 Shadowflame damage.\n\nIf you consume this potion while your weapon is augmented with Shadowcore Oil, the additional damage is increased by 10%. Lasts 25 sec. (5 Min Cooldown)\nSell Price:" }
entries[171350] = { ["name"] = "Potion of Divine Awakening", ["text"] = "Use: Your healing spells are increased by up to 11765 , based on the target's missing health.\n\nIf you consume this potion while your weapon is augmented with Embalmer's Oil, the additional healing is increased by 10%. Lasts 25 sec. (5 Min Cooldown)\nSell Price:" }
entries[171351] = { ["name"] = "Potion of Deathly Fixation", ["text"] = "Use: Your damaging spells and abilities have a chance to apply Deathly Fixation to your target, dealing 172 Shadow damage over 8 sec and stacking up to 5 times. Upon reaching 5 stacks, Deathly Fixation explodes, dealing 3946 Shadow damage to the target.\n\nIf you consume this potion while your weapon is augmented with Shadowcore Oil, the explosion damage is increased by 10%. Lasts 25 sec. (5 Min Cooldown)\nSell Price:" }
entries[171352] = { ["name"] = "Potion of Empowered Exorcisms", ["text"] = "Use: Your damaging spells and abilities have a chance erupt your target's anima, dealing up to 3740 Shadow damage to all enemies within 10 yards of the target.\n\nIf you consume this potion while your weapon is augmented with Shadowcore Oil, the additional damage and range is increased by 20%. Lasts 25 sec. (5 Min Cooldown)\nSell Price:" }
